 master=OUT/(key+'.png');record=read(Path(str(master)+'.generation.json'));inputfile=OUT/f'generation/{key}.submitted-input.json';inp=read(inputfile);call=calls[key]
 require(inp==call['input'],'function-store input equality '+key);require(record['sha256']==sha(master),'masterSHA '+key);require(record['submittedInputFileSha256']==sha(inputfile),'inputFileSHA '+key)
